function closeDetail(){const id=selectedId;detailGeneration++;selectedId=null;selectedDetail=null;$('#detail-dialog').close();const selector=view==='delivery'?'[data-flow-incident]':view==='clients'?'[data-token-incident]':'[data-incident]';const current=[...document.querySelectorAll(selector)].find((node)=>(node.dataset.flowIncident ?? node.dataset.tokenIncident ?? node.dataset.incident)===id);(current ?? (selectedTrigger?.isConnected ? selectedTrigger : $('#main'))).focus();}
