function disconnect(){token='';generation++;detailGeneration++;clientsGeneration++;activityGeneration++;overview=null;items=[];hasMore=false;updatedAt=null;offset=0;selectedId=null;selectedDetail=null;if($('#detail-dialog').open)$('#detail-dialog').close();$('#detail-content').replaceChildren();$('#admin-token').value='';$('#admin-name').textContent='운영 관리자';$('#refresh').disabled=true;$('#disconnect').hidden=true;$('#connect-open').textContent='서버 연결';for(const id of ['metric-open','metric-ack','metric-resolved','metric-urgent','nav-count'])$(`#${id}`).textContent='—';$('#empty-state').innerHTML=`<div class="empty-icon">${icon('layers')}</div><h2>사건의 맥락을 한곳에서</h2><p>서버에 연결하면 수집된 사건과<br>담당 상태를 확인할 수 있어요.</p><button class="jk-btn jk-btn-primary" id="empty-connect">서버 연결</button>`;renderRows();connection('');message('');$('#updated-at').textContent='아직 갱신하지 않음';$('#mock-banner').hidden=true;$('#delivery-view').replaceChildren();$('#settings-view').replaceChildren();$('#clients-view').replaceChildren();setView('incidents');}
$('#connect-form').addEventListener('submit',async(event)=>{event.preventDefault();const candidate=$('#admin-token').value;if(credentialPending || (token && candidate!==token && $('#new-token')?.hidden===false)){$('#connect-error').textContent='표시된 토큰을 먼저 복사한 뒤 복사 완료를 눌러 주세요.';$('#connect-error').hidden=false;return;}$('#connect-submit').disabled=true;$('#connect-submit').textContent='연결 중…';$('#connect-error').hidden=true;try{await api('/v1/admin',{},candidate);if(token && token!==candidate){clientsGeneration++;activityGeneration++;$('#clients-view').replaceChildren();overview=null;}token=candidate;$('#admin-token').value='';$('#connect-dialog').close();$('#disconnect').hidden=false;$('#connect-open').textContent='연결 관리';await refresh();toast('운영 서버에 연결했어요.');}catch(error){$('#connect-error').textContent=error.message;$('#connect-error').hidden=false;$('#admin-token').focus();}finally{$('#connect-submit').disabled=credentialPending;$('#connect-submit').textContent='연결';}});
