$('#filter-form').addEventListener('submit',(event)=>{event.preventDefault();offset=0;refresh();});$('#priority').addEventListener('change',()=>{offset=0;renderLevels();refresh();});$('#level-grid').addEventListener('click',(event)=>{const cell=event.target.closest('[data-level-rank]');if(!cell)return;$('#priority').value=$('#priority').value===cell.dataset.levelRank?'':cell.dataset.levelRank;offset=0;renderLevels();refresh();});$('#reset-filters').addEventListener('click',()=>resetFilters());
