async function retryDelivery(button){if(!confirm('이 발송을 다시 시도할까요? 다른 채널로 이미 전달됐을 수 있습니다.'))return;const incident=selectedId;const path=button.dataset.retryChannel?`channel-deliveries/${encodeURIComponent(button.dataset.retryChannel)}`:button.dataset.retrySlack?`slack-deliveries/${encodeURIComponent(button.dataset.retrySlack)}`:`messages/${encodeURIComponent(button.dataset.retryMessage)}`;button.disabled=true;try{await api(`/v1/admin/${path}/retry`,{method:'POST'});toast('발송을 다시 시도합니다.');await refresh();if(incident && selectedId===incident)await openDetail(incident);}catch(error){toast(error.message);if(button.isConnected)button.disabled=false;}}
for(const selector of ['#delivery-view','#detail-content'])$(selector).addEventListener('click',(event)=>{const button=event.target.closest('[data-retry-channel],[data-retry-slack],[data-retry-message]');if(button)retryDelivery(button);});
$('#delivery-view').addEventListener('click',(event)=>{const trigger=event.target.closest('[data-flow-incident]');if(trigger)openDetail(trigger.dataset.flowIncident,trigger);});
