fetch('/v1/admin-mode',{cache:'no-store'}).then((response)=>{if(!response.ok)throw new Error('server unavailable');return response.json();}).then((mode)=>{modePending=false;document.querySelectorAll('[aria-controls="connect-dialog"]').forEach((button)=>button.hidden=mode.development);if(mode.development){token='development';refresh();}else if(view!=='incidents')setView(view);}).catch(()=>{modePending=false;document.querySelectorAll('[aria-controls="connect-dialog"]').forEach((button)=>button.hidden=false);connection('failed');message('서버 상태를 확인하지 못했어요. 연결을 확인한 뒤 다시 시도하세요.');if(view!=='incidents')setView(view);});

{const day=(offset)=>{const d=new Date(Date.now()+offset*86400000);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;};$('#evidence-from').value=day(-29);$('#evidence-to').value=day(0);}
$('#evidence-form').addEventListener('submit',async(e)=>{e.preventDefault();const button=e.submitter ?? e.currentTarget.querySelector('[type=submit]');button.disabled=true;$('#evidence-error').hidden=true;try{const query=new URLSearchParams({from:$('#evidence-from').value,to:$('#evidence-to').value,offset_minutes:String(-new Date().getTimezoneOffset())});let response;try{response=await fetch(`/v1/admin/evidence.csv?${query}`,{cache:'no-store',signal:AbortSignal.timeout(30000),headers:{Authorization:`Bearer ${token}`}});}catch{throw new Error('서버에 연결하지 못했어요. 네트워크와 서버 상태를 확인하세요.');}if(response.status===422)throw new Error('시작일이 종료일보다 늦지 않게, 92일 이내로 고르세요.');if(!response.ok)throw new Error(`CSV를 만들지 못했어요. (HTTP ${response.status})`);const url=URL.createObjectURL(await response.blob());const link=document.createElement('a');link.href=url;link.download=`noti-mesh-evidence-${$('#evidence-from').value}-${$('#evidence-to').value}.csv`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('CSV를 내려받았어요.');}catch(error){$('#evidence-error').textContent=error.message;$('#evidence-error').hidden=false;}finally{button.disabled=false;}});
async function loadSilences(){
 const area=$('#silences-view');
 try{const data=await api('/v1/admin/silences');if(view!=='silences')return;const readOnly=overview?.administrator?.role==='viewer';const services=[...new Set((overview?.routes ?? []).map((r)=>r.service))].sort();
 const status=(s)=>s.cancelled_at?`취소 ${escape(date(s.cancelled_at))}${s.cancelled_by?` (${escape(s.cancelled_by)})`:''}`:s.active?'진행 중':'종료';
 area.innerHTML=`<div class="settings-block"><h2>점검 무음 시작</h2><p>무음 중에 열린 사건은 기록만 하고, 무음이 끝날 때 아직 열려 있으면 그때 알립니다. 무음 중에 해결된 사건과 일반 메시지는 보내지 않습니다. 무음 전에 알린 사건의 해결 알림은 그대로 보냅니다.${readOnly?' 현재 계정은 읽기 전용입니다.':''}</p><form id="silence-form" class="silence-form"><label class="jk-label" for="silence-service">서비스</label><input class="jk-input" id="silence-service" list="silence-services" maxlength="256" required ${readOnly?'disabled':''}><datalist id="silence-services">${services.map((v)=>`<option value="${escape(v)}">`).join('')}</datalist><label class="jk-label" for="silence-environment">환경 (비우면 모든 환경)</label><input class="jk-input" id="silence-environment" maxlength="256" placeholder="production" ${readOnly?'disabled':''}><label class="jk-label" for="silence-minutes">기간</label><select class="jk-select" id="silence-minutes" ${readOnly?'disabled':''}>${[[30,'30분'],[60,'1시간'],[120,'2시간'],[240,'4시간'],[480,'8시간'],[1440,'24시간']].map(([v,l])=>`<option value="${v}" ${v===60?'selected':''}>${l}</option>`).join('')}</select><label class="jk-label" for="silence-reason">사유</label><input class="jk-input" id="silence-reason" maxlength="500" required placeholder="DB 정기 점검" ${readOnly?'disabled':''}><button class="jk-btn jk-btn-primary" type="submit" ${readOnly?'disabled':''}>지금부터 무음</button></form><p id="silence-error" class="form-error" role="alert" hidden></p></div><div class="settings-block"><h2>무음 기록</h2>${data.items.map((s)=>`<div class="settings-row"><div><strong>${escape(s.service)} / ${escape(s.environment ?? '모든 환경')}</strong><small>${escape(s.reason)} · ${escape(date(s.starts_at))} ~ ${escape(date(s.ends_at))} · 작성 ${escape(s.created_by)}<br>${status(s)} · 보류 중 사건 ${Number(s.held_incidents)}건 · 보류한 메시지 ${Number(s.held_messages)}건</small></div><span>${s.active && !readOnly?`<button class="jk-btn" data-cancel-silence="${escape(s.id)}">지금 종료</button>`:''}</span></div>`).join('')||'<p>무음 기록이 없어요.</p>'}</div>`;
 $('#silence-form').addEventListener('submit',async(e)=>{e.preventDefault();const button=e.submitter ?? e.currentTarget.querySelector('[type=submit]');button.disabled=true;$('#silence-error').hidden=true;try{await api('/v1/admin/silences',{method:'POST',body:JSON.stringify({service:$('#silence-service').value,environment:$('#silence-environment').value||null,minutes:Number($('#silence-minutes').value),reason:$('#silence-reason').value})});toast('점검 무음을 시작했어요.');await loadSilences();}catch(error){$('#silence-error').textContent=error.status===422?'서비스와 사유를 입력하세요.':error.message;$('#silence-error').hidden=false;button.disabled=false;}});
 for(const button of area.querySelectorAll('[data-cancel-silence]'))button.addEventListener('click',async()=>{if(!confirm('무음을 지금 종료할까요? 보류 중인 열린 사건은 곧 알립니다.'))return;button.disabled=true;try{await api(`/v1/admin/silences/${encodeURIComponent(button.dataset.cancelSilence)}/cancel`,{method:'POST',body:'{}'});toast('무음을 종료했어요.');await loadSilences();}catch(error){toast(error.message);button.disabled=false;}});
 }catch(error){if(view!=='silences')return;area.innerHTML=`<div class="settings-block"><h2>무음 기록을 불러오지 못했어요</h2><p class="form-error" role="alert">${escape(error.message)}</p></div>`;}
}
async function loadClients(){
 const mine=++clientsGeneration;const area=$('#clients-view');area.innerHTML='<div class="settings-block" role="status">토큰 목록을 불러오는 중이에요.</div>';
 try{const data=await api('/v1/admin/tokens');if(mine!==clientsGeneration||view!=='clients')return;const readOnly=overview?.administrator?.role==='viewer';area.innerHTML=`<div class="settings-block"><h2>클라이언트 토큰 발급</h2><p>발급한 토큰은 한 번만 표시됩니다. 지정한 서비스의 이벤트만 보낼 수 있습니다.${readOnly ? ' 현재 계정은 읽기 전용입니다.' : ''}</p><form id="token-form"><label class="jk-label" for="client-name">클라이언트 이름</label><input class="jk-input" id="client-name" maxlength="128" required ${readOnly?'disabled':''}><label class="jk-label" for="client-service">서비스 식별자</label><input class="jk-input" id="client-service" maxlength="256" required ${readOnly?'disabled':''}><button class="jk-btn jk-btn-primary" type="submit" ${readOnly?'disabled':''}>토큰 생성</button></form><div id="new-token" hidden><p>지금 토큰을 복사하세요. 다시 표시할 수 없습니다.</p><code id="new-token-value"></code><p>Slack Incoming Webhook을 쓰던 발신자는 아래 URL로 바꾸면 됩니다. 환경은 <code>?environment=</code>로 지정하며 기본값은 production입니다.</p><code id="new-token-hook"></code><div><button id="token-saved" type="button" class="jk-btn">복사 완료</button></div></div><p id="token-error" class="form-error" role="alert" hidden></p></div><div class="settings-block"><h2>발급된 토큰</h2>${data.items.map((t)=>`<div class="settings-row"><div><strong>${escape(t.name)}</strong><small>${escape(t.service)} · 생성 ${escape(date(t.created_at))} · 마지막 교체 ${escape(date(t.rotated_at))} · 마지막 사용 ${escape(date(t.last_used_at))}<br>${(t.audit ?? []).slice(0,3).map((a)=>`${{created:'발급',rotated:'교체',revoked:'폐기'}[a.action]} ${escape(date(a.created_at))} (${a.actor_kind==='unknown'?'작업자 정보 없음':a.actor_kind==='development'?'개발 모드':a.actor_kind==='named_admin'?escape(a.actor):'공유 관리자'})`).join(' · ')}</small></div><span><button class="jk-btn" data-activity="${escape(t.id)}">전송 이력</button> ${t.revoked_at?'폐기됨':readOnly?'읽기 전용':`<button class="jk-btn" data-rotate="${escape(t.id)}">교체</button> <button class="jk-btn" data-revoke="${escape(t.id)}">폐기</button>`}</span></div>`).join('')||'<p>발급된 토큰이 없어요.</p>'}</div><div id="client-activity" class="settings-block" hidden></div>`;
 $('#token-saved').addEventListener('click',()=>{$('#new-token-value').textContent='';$('#new-token-hook').textContent='';$('#new-token').hidden=true;loadClients();});
 $('#token-form').addEventListener('submit',async(e)=>{e.preventDefault();const button=e.submitter;button.disabled=true;setCredentialPending(true);try{const result=await api('/v1/admin/tokens',{method:'POST',body:JSON.stringify({name:$('#client-name').value,service:$('#client-service').value})});$('#new-token').hidden=false;$('#new-token-value').textContent=result.token;$('#new-token-hook').textContent=`${location.origin}/hooks/slack/${result.token}`;button.disabled=true;toast('토큰을 복사한 뒤 복사 완료를 눌러 주세요.');}catch(error){$('#token-error').textContent=error.message;$('#token-error').hidden=false;button.disabled=false;}finally{setCredentialPending(false);}});
 for(const button of area.querySelectorAll('[data-activity]'))button.addEventListener('click',async()=>{button.disabled=true;const request=++activityGeneration;const panel=$('#client-activity');panel.hidden=false;panel.innerHTML='<h2>전송 이력</h2><p role="status">이력을 불러오고 있어요.</p>';try{const result=await api(`/v1/admin/tokens/${encodeURIComponent(button.dataset.activity)}/activity`);if(request!==activityGeneration||!panel.isConnected||view!=='clients')return;panel.innerHTML=`<h2>전송 이력</h2><p>최대 100건을 표시합니다. 접수 시각이 있는 기록은 최신순이며, 거부된 요청은 포함하지 않습니다.</p>${result.items.map((entry)=>`<div class="settings-row"><div>${entry.kind==='event'?`<button class="incident-title" data-token-incident="${escape(entry.reference_id)}">${escape(entry.title)}</button>`:`<strong>${escape(entry.title)}</strong>`}<small>${entry.kind==='event'?'장애 이벤트':'일반 메시지'} · ${escape(entry.event_id)}<br>접수 ${entry.received_at?escape(fullTime(entry.received_at)):'시각 기록 없음'}${entry.occurred_at?` · 발생 ${escape(fullTime(entry.occurred_at))}`:''}</small></div></div>`).join('')||'<p>접수한 기록이 없어요.</p>'}`;for(const trigger of panel.querySelectorAll('[data-token-incident]'))trigger.addEventListener('click',()=>openDetail(trigger.dataset.tokenIncident,trigger));panel.scrollIntoView({block:'nearest'});}catch(error){if(request!==activityGeneration||!panel.isConnected||view!=='clients')return;panel.innerHTML=`<h2>전송 이력</h2><p class="form-error" role="alert">${escape(error.message)}</p>`;}finally{button.disabled=false;}});
 for(const button of area.querySelectorAll('[data-rotate]'))button.addEventListener('click',async()=>{if(!$('#new-token').hidden){toast('표시된 토큰을 먼저 복사한 뒤 복사 완료를 눌러 주세요.');return;}if(!confirm('토큰을 교체하면 기존 토큰이 즉시 작동을 멈춥니다. 교체할까요?'))return;button.disabled=true;setCredentialPending(true);try{const result=await api(`/v1/admin/tokens/${encodeURIComponent(button.dataset.rotate)}/rotate`,{method:'POST'});$('#new-token').hidden=false;$('#new-token-value').textContent=result.token;$('#new-token-hook').textContent=`${location.origin}/hooks/slack/${result.token}`;$('#token-form button').disabled=true;toast('새 토큰을 복사한 뒤 복사 완료를 눌러 주세요.');}catch(error){toast(error.message);button.disabled=false;}finally{setCredentialPending(false);}});
 for(const button of area.querySelectorAll('[data-revoke]'))button.addEventListener('click',async()=>{if(!$('#new-token').hidden){toast('표시된 토큰을 먼저 복사한 뒤 복사 완료를 눌러 주세요.');return;}if(!confirm('이 토큰을 폐기할까요? 클라이언트의 전송이 중단됩니다.'))return;button.disabled=true;try{await api(`/v1/admin/tokens/${encodeURIComponent(button.dataset.revoke)}/revoke`,{method:'POST'});await loadClients();}catch(error){toast(error.message);button.disabled=false;}});
 }catch(error){if(mine!==clientsGeneration||view!=='clients')return;area.innerHTML=`<div class="settings-block"><p class="form-error">${escape(error.message)}</p><button id="reload-clients" class="jk-btn">다시 시도</button></div>`;$('#reload-clients').addEventListener('click',loadClients);}
}

$('#settings-view').addEventListener('click', async (event)=>{
  if(event.target.id!=='slack-load')return;
  const panel=$('#slack-config'), button=event.target;
  button.disabled=true;button.textContent='불러오는 중…';
  try{
    const data=await api('/v1/admin/slack-test');
    if(!panel.isConnected)return;
    panel.innerHTML=`<div class="slack-workspace"><span>연결된 워크스페이스</span><strong>${escape(data.workspace)}</strong></div><form id="slack-test-form"><div class="slack-fields"><div class="slack-field"><label class="jk-label" for="slack-channel">발송 채널</label><select id="slack-channel" class="jk-select" aria-describedby="slack-channel-help" required><option value="">채널을 선택하세요</option>${data.channels.map((c)=>`<option value="${escape(c.id)}" ${c.id===data.selected_channel?'selected':''}>#${escape(c.name)}</option>`).join('')}</select><p id="slack-channel-help">${data.channels.length?'봇이 참가한 채널만 표시합니다.':'표시할 채널이 없어요. Slack에서 봇을 초대해 주세요.'}${data.private_available?'':' 비공개 채널에는 groups:read 권한이 필요합니다.'}</p></div><div class="slack-field"><label class="jk-label" for="slack-user">담당 사용자</label><select id="slack-user" class="jk-select" aria-describedby="slack-user-selected slack-user-help" required><option value="">담당자를 선택하세요</option>${data.users.map((u)=>`<option value="${escape(u.id)}" ${u.id===data.selected_user?'selected':''}>${escape(u.name)} (${escape(u.id)})</option>`).join('')}</select><p id="slack-user-selected" class="slack-selected-user" hidden></p><p id="slack-user-help">사건을 맡을 담당자입니다. 메시지 확인은 다른 사용자도 할 수 있어요.</p></div></div><div class="slack-form-footer"><button class="jk-btn jk-btn-primary" type="submit">설정 저장</button><p>저장 후 서버를 다시 시작하면 적용됩니다.</p></div><p id="slack-test-result" role="status" aria-live="polite" hidden></p></form>`;
    const selected=panel.querySelector('#slack-user-selected');
    const user=panel.querySelector('#slack-user');
    if(user.value){selected.textContent=`선택: ${user.selectedOptions[0].textContent}`;selected.hidden=false;}
  }catch(error){
    if(!panel.isConnected)return;
    panel.innerHTML=`<p class="form-error" role="alert">목록을 불러오지 못했어요. Slack 앱의 channels:read·users:read 권한과 설치 상태를 확인하세요.</p><button class="jk-btn" id="slack-load" type="button">다시 시도</button>`;
  }
});
$('#settings-view').addEventListener('submit',async(event)=>{
  if(event.target.id!=='slack-test-form')return;
  event.preventDefault();
  const form=event.target, button=form.querySelector('button'), result=form.querySelector('#slack-test-result');
  button.disabled=true;button.textContent='저장 중…';result.hidden=true;
  try{
    await api('/v1/admin/slack-test',{method:'POST',body:JSON.stringify({channel_id:form.querySelector('#slack-channel').value,user_id:form.querySelector('#slack-user').value})});
    if(!form.isConnected)return;
    result.className='slack-result success';result.textContent='설정을 저장했어요. 서버를 다시 시작하면 적용됩니다.';result.hidden=false;
  }catch(error){
    if(!form.isConnected)return;
    result.className='slack-result error';result.textContent='저장하지 못했어요. 선택한 값과 서버 상태를 확인한 뒤 다시 시도하세요.';result.hidden=false;
  }finally{if(button.isConnected){button.disabled=false;button.textContent='설정 저장';}}
});
$('#settings-view').addEventListener('change',(event)=>{
  if(!event.target.closest('#slack-test-form'))return;
  if(event.target.id==='slack-user'){
    const selected=$('#slack-user-selected');
    selected.hidden=!event.target.value;
    selected.textContent=event.target.value?`선택: ${event.target.selectedOptions[0].textContent}`:'';
  }
  const result=$('#slack-test-result');
  if(result)result.hidden=true;
});
